mapper.update:
update bbs_collect_activity
title = #{title}, status = #{status}, scope_type = #{scopeType}, scope_value = #{scopeValue}, start_time = #{startTime}, end_time = #{endTime}, anonymous_flag = #{anonymousFlag}, realtime_flag = #{realtimeFlag}, limit_once_flag = #{limitOnceFlag}, biz_id = #{bizId}, banner_url = #{bannerUrl}, rule_text = #{ruleText}, remark = #{remark}, update_time = now()
where activity_id = #{activityId}

mapper.select:
select a.activity_id, a.title, a.activity_type, a.status, a.creator_user_id, a.creator_nick_name, a.scope_type, a.scope_value, a.start_time, a.end_time, a.anonymous_flag, a.realtime_flag, a.limit_once_flag, a.biz_id, a.participant_count, a.banner_url, a.rule_text, a.remark, a.create_time, a.update_time, case when p.user_id is null then '0' else '1' end as has_participated from bbs_collect_activity a left join bbs_collect_participation p on p.activity_id = a.activity_id and p.user_id = #{currentUserId} and p.submit_status = 'SUBMITTED' left join sys_user cu on cu.user_id = #{currentUserId} left join sys_dept cd on cd.dept_id = cu.dept_id
and a.activity_type = #{activityType}
and a.status = #{status}
and a.title like concat('%', #{keyword}, '%')
and a.status != 'DELETED' and ( a.activity_type != 'vote' or a.creator_user_id = #{currentUserId} or a.scope_type = 'all' or (a.scope_type = 'users' and find_in_set(#{currentUserId}, a.scope_value)) or (a.scope_type = 'org' and find_in_set(concat('U_', #{currentUserId}), a.scope_value)) or ( a.scope_type = 'dept' and cu.dept_id is not null and ( concat(',', a.scope_value, ',') like concat('%,', cast(cu.dept_id as char), ',%') or ( cd.ancestors is not null and concat(',', a.scope_value, ',') collate utf8mb4_general_ci regexp (concat(',(', replace(cd.ancestors, ',', '|'), '),') collate utf8mb4_general_ci) ) ) ) or ( a.scope_type = 'org' and cu.dept_id is not null and ( concat(',', a.scope_value, ',') like concat('%,D_', cast(cu.dept_id as char), ',%') or ( cd.ancestors is not null and concat(',', a.scope_value, ',') collate utf8mb4_general_ci regexp (concat(',(D_', replace(cd.ancestors, ',', '|D_'), '),') collate utf8mb4_general_ci) ) ) ) )
order by a.create_time desc

select count(1) from bbs_collect_participation
where activity_id = #{activityId} and user_id = #{userId}

    and submit_status = #{status}

select ticket_id, activity_id, form_id, submit_user_id, submit_nick_name, demand_name, demand_type, demand_detail, priority, attachment_urls, contact_person, custom_field_json, status, assignee_user_id, assignee_nick_name, process_comment, create_time, update_time from bbs_collect_demand_ticket
activity_id = #{activityId}
and status = #{status}
and (demand_name like concat('%', #{keyword}, '%') or demand_detail like concat('%', #{keyword}, '%'))
order by create_time desc

mapper.update:
update bbs_collect_demand_ticket
set assignee_user_id = #{assigneeUserId}, assignee_nick_name = #{assigneeNickName}, update_time = now()
where ticket_id = #{ticketId}

update bbs_collect_demand_ticket
set status = #{status}, process_comment = #{comment}, update_time = now()
where ticket_id = #{ticketId}

mapper.select:
select question_id, activity_id, question_no, question_type, question_title, option_json, jump_logic_json, required_flag
from bbs_collect_survey_question where activity_id = #{activityId}
order by question_no asc, question_id asc
